// Generates a blog cover in the NOIR technical line drawing style.
//
//   node scripts/blog-cover.mjs <slug> "<scene in English>" [output.webp]
//
// The scene must name the one element that receives the highlight. The image
// is generated by the Codex CLI and saved as public/blog/<slug>.webp, 1600x900.
import { spawnSync } from "node:child_process";
import { existsSync, mkdtempSync, readdirSync, rmSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const WIDTH = 1600;
const HEIGHT = 900;
const MODEL = process.env.BLOG_COVER_MODEL ?? "gpt-5.6-terra";
const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

const STYLE = [
  "technical blueprint line drawing, thin precise off-white lines on pure black,",
  "isometric view, like an architect's wireframe plan, no fills, no shading,",
  "even line weight, lots of fine detail, the scene fills the whole frame edge to edge.",
  "Exactly one element is highlighted by a slightly brighter outline with a faint,",
  "soft, smooth prismatic glow (the only colour in the image, a subtle continuous",
  "spectrum, never saturated neon and never separate colour bands).",
  "Fine dotted measurement lines around the highlighted element.",
  "No text, no letters, no numbers, no logos. Wide 16:9 landscape image.",
].join(" ");

const [slug, scene, outputArgument] = process.argv.slice(2);

if (!slug || !scene || !SLUG_PATTERN.test(slug)) {
  console.error('Usage: node scripts/blog-cover.mjs <slug> "<scene in English>" [output.webp]');
  process.exit(1);
}

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const output = outputArgument
  ? path.resolve(outputArgument)
  : path.join(root, "public", "blog", `${slug}.webp`);
const workDirectory = mkdtempSync(path.join(os.tmpdir(), "noir-blog-cover-"));

const prompt = [
  "Use your image generation tool to create one image.",
  `Subject: ${scene}`,
  `Style: ${STYLE}`,
  "Save the final image in the current directory as cover.png and reply with only the file path.",
].join(" ");

// The prompt goes through stdin so that quotes in it never reach the shell.
const codex = spawnSync(
  `codex exec --skip-git-repo-check -s workspace-write -m ${MODEL} -c model_reasoning_effort=low -`,
  { cwd: workDirectory, encoding: "utf8", input: prompt, shell: true },
);
const log = `${codex.stdout ?? ""}\n${codex.stderr ?? ""}`;

function findGeneratedImage() {
  const saved = path.join(workDirectory, "cover.png");
  if (existsSync(saved)) return saved;

  // The Codex sandbox sometimes fails to copy the image out of its own store.
  const sessionId = log.match(/session id: ([0-9a-f-]+)/)?.[1];
  if (!sessionId) return null;
  const store = path.join(os.homedir(), ".codex", "generated_images", sessionId);
  if (!existsSync(store)) return null;
  const image = readdirSync(store).find((name) => name.endsWith(".png"));
  return image ? path.join(store, image) : null;
}

const source = findGeneratedImage();

if (!source) {
  console.error(log.trim().split("\n").slice(-15).join("\n"));
  console.error(`\nNo image was generated for "${slug}".`);
  process.exit(1);
}

await sharp(source).resize(WIDTH, HEIGHT, { fit: "cover" }).webp({ quality: 84 }).toFile(output);
rmSync(workDirectory, { force: true, recursive: true });

console.log(output);
